def check_adult_query(api_key, keyword, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0298000" if __import__("os").path.isdir("./environment_mix/0298000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start_ts = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    _CROCK = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid():
        ms = int(time.time() * 1000)
        t = ms
        out = []
        for _ in range(10):
            out.append(_CROCK[t % 32])
            t //= 32
        out = out[::-1]
        r = random.getrandbits(80)
        out2 = []
        for _ in range(16):
            out2.append(_CROCK[r % 32])
            r //= 32
        return "".join(out + out2)

    def _sha256(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _normalize_keyword(kw):
        if not isinstance(kw, str):
            return None
        k = kw.strip()
        if len(k) < 1 or len(k) > 255:
            return None
        return k

    def _day_window_start(dt):
        d = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _advance_req_status(req, new_status):
        transitions = {
            "received": {"validated", "failed"},
            "validated": {"upstream_requested", "failed"},
            "upstream_requested": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
        }
        cur = req.get("status")
        if cur not in transitions or new_status not in transitions[cur]:
            return False
        req["status"] = new_status
        req["updated_at"] = _iso(now)
        return True

    def _get_or_create_counter(counters, api_key_id, wstart_iso):
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == "day" and c.get("window_start") == wstart_iso:
                return c
        c = {
            "id": _ulid(),
            "api_key_id": api_key_id,
            "window_start": wstart_iso,
            "window_type": "day",
            "requests_total": 0,
            "requests_succeeded": 0,
            "requests_failed": 0,
            "result_items_total": 0,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        counters.append(c)
        return c

    def _auth_key(api_key_value, api_keys_rows):
        if not isinstance(api_key_value, str) or not api_key_value:
            return None
        presented = api_key_value.strip()
        if not presented:
            return None
        presented_hash = _sha256(presented)
        for r in api_keys_rows:
            if r.get("id") == presented:
                return r
        for r in api_keys_rows:
            if r.get("key_hash") == presented_hash:
                return r
        for r in api_keys_rows:
            if isinstance(r.get("key_prefix"), str) and presented.startswith(r.get("key_prefix")):
                return r
        return None

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    response_cache = _load("response_cache.json")
    usage_counters = _load("usage_counters.json")
    search_items = _load("search_result_items.json")  # unchanged for this tool, but persisted for consistency

    key_row = _auth_key(api_key, api_keys)
    if not key_row or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Invalid or inactive api_key.")

    req_id = _ulid()
    req = {
        "id": req_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "check_adult_query",
        "keyword": None,
        "page": None,
        "display": None,
        "start": None,
        "sort": None,
        "filter": None,
        "normalized_params": {},
        "cache_key": "",
        "cache_hit": False,
        "status": "received",
        "upstream_endpoint": "/v1/search/adult.json",
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "response_meta": None,
        "raw_response_ref": None,
        "result_items_count": 0,
        "duration_ms": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    request_logs.append(req)

    def _finalize(resp):
        req["duration_ms"] = max(0, int((time.time() - start_ts) * 1000))
        _save("request_logs.json", request_logs)
        _save("usage_counters.json", usage_counters)
        _save("response_cache.json", response_cache)
        _save("api_keys.json", api_keys)
        _save("search_result_items.json", search_items)
        return resp

    norm_kw = _normalize_keyword(keyword)
    if norm_kw is None:
        _advance_req_status(req, "failed")
        req["error_code"] = "VALIDATION_ERROR"
        req["error_message"] = "keyword must be a non-empty string of length 1..255 after trimming."
        return _finalize(_err("VALIDATION_ERROR", req["error_message"]))

    if use_cache is not None and not isinstance(use_cache, bool):
        _advance_req_status(req, "failed")
        req["error_code"] = "VALIDATION_ERROR"
        req["error_message"] = "use_cache must be boolean when provided."
        return _finalize(_err("VALIDATION_ERROR", req["error_message"]))

    normalized = {
        "keyword": norm_kw,
        "use_cache": bool(use_cache) if use_cache is not None else False,
    }
    req["keyword"] = norm_kw
    req["normalized_params"] = normalized

    scope = key_row.get("naver_client_id") or ""
    canon = json.dumps(normalized, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    cache_key = _sha256("check_adult_query|" + scope + "|" + canon)
    req["cache_key"] = cache_key

    if not _advance_req_status(req, "validated"):
        _advance_req_status(req, "failed")
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal request status transition."
        return _finalize(_err("INVALID_TRANSITION", req["error_message"]))

    # rate limit
    rps = key_row.get("rate_limit_rps")
    burst = key_row.get("rate_limit_burst")
    recent = []
    for rl in request_logs:
        if rl.get("api_key_id") != key_row.get("id"):
            continue
        created = _parse_dt(rl.get("created_at"))
        if created:
            recent.append(created.timestamp())
    recent.sort(reverse=True)
    try:
        window_sec = float(burst) / float(rps)
    except Exception:
        window_sec = 0.0
    cutoff = now.timestamp() - window_sec
    cnt = 0
    for t in recent:
        if t >= cutoff:
            cnt += 1
        else:
            break
    if window_sec > 0 and cnt > burst:
        _advance_req_status(req, "failed")
        req["error_code"] = "RATE_LIMIT"
        req["error_message"] = "Rate limit exceeded."
        wstart = _day_window_start(now)
        c = _get_or_create_counter(usage_counters, key_row.get("id"), _iso(wstart))
        c["requests_total"] += 1
        c["requests_failed"] += 1
        c["updated_at"] = _iso(now)
        return _finalize(_err("RATE_LIMIT", req["error_message"], error_code="RATE_LIMIT"))

    wstart = _day_window_start(now)
    counter = _get_or_create_counter(usage_counters, key_row.get("id"), _iso(wstart))
    if counter.get("requests_total", 0) + 1 > int(key_row.get("quota_day_requests", 0)):
        _advance_req_status(req, "failed")
        req["error_code"] = "QUOTA_EXCEEDED"
        req["error_message"] = "Daily request quota exceeded."
        counter["requests_total"] += 1
        counter["requests_failed"] += 1
        counter["updated_at"] = _iso(now)
        return _finalize(_err("QUOTA_EXCEEDED", req["error_message"], error_code="quota_day_requests"))

    # cache serve
    cache_hit = False
    served_meta = None
    if normalized["use_cache"]:
        for ce in response_cache:
            if ce.get("cache_key") == cache_key and ce.get("tool_name") == "check_adult_query" and ce.get("status") == "fresh":
                exp = _parse_dt(ce.get("expires_at"))
                if exp and exp > now:
                    cache_hit = True
                    served_meta = ce.get("response_meta")
                    break

    counter["requests_total"] += 1
    counter["updated_at"] = _iso(now)

    if cache_hit:
        req["cache_hit"] = True
        _advance_req_status(req, "upstream_requested")
        _advance_req_status(req, "succeeded")
        req["response_meta"] = served_meta or {"adult": False, "cached": True}
        req["result_items_count"] = 0
        counter["requests_succeeded"] += 1
        key_row["last_used_at"] = _iso(now)
        key_row["updated_at"] = _iso(now)
        return _finalize({"request": req, "result": req["response_meta"], "cache": {"hit": True, "cache_key": cache_key}})

    if not _advance_req_status(req, "upstream_requested"):
        _advance_req_status(req, "failed")
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal request status transition."
        counter["requests_failed"] += 1
        return _finalize(_err("INVALID_TRANSITION", req["error_message"]))

    # deterministic classification (offline)
    adult_terms = [
        "porn", "sex", "xxx", "av", "야동", "성인", "섹스", "포르노", "누드", "19금", "자위", "야사", "노모", "유두",
    ]
    lower = norm_kw.lower()
    is_adult = any(t in lower for t in adult_terms)

    meta = {
        "keyword": norm_kw,
        "adult": bool(is_adult),
        "confidence": 0.9 if is_adult else 0.6,
        "checked_at": _iso(now),
    }
    req["response_meta"] = meta
    req["result_items_count"] = 0

    if not _advance_req_status(req, "succeeded"):
        _advance_req_status(req, "failed")
        req["error_code"] = "INVALID_TRANSITION"
        req["error_message"] = "Illegal request status transition."
        counter["requests_failed"] += 1
        return _finalize(_err("INVALID_TRANSITION", req["error_message"]))

    counter["requests_succeeded"] += 1
    counter["updated_at"] = _iso(now)
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)

    expires = now + datetime.timedelta(seconds=3600)
    response_cache.append({
        "id": _ulid(),
        "cache_key": cache_key,
        "tool_name": "check_adult_query",
        "normalized_params": normalized,
        "status": "fresh",
        "response_meta": meta,
        "raw_response_ref": None,
        "items_ref": None,
        "expires_at": _iso(expires),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })

    return _finalize({"request": req, "result": meta, "cache": {"hit": False, "cache_key": cache_key, "expires_at": _iso(expires)}})

def search_encyclopedia(api_key, keyword, page=None, display=None, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0298000" if __import__("os").path.isdir("./environment_mix/0298000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid():
        # 26-char Crockford base32 ULID-like (time + randomness). Not perfect ULID spec, but stable id convention.
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        # 48-bit time -> 10 chars
        t = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        out = out[::-1]
        # 80-bit randomness -> 16 chars
        r = random.getrandbits(80)
        rand = []
        for _ in range(16):
            rand.append(alphabet[r & 31])
            r >>= 5
        return "".join(out + rand[::-1])

    def _stable_json(o):
        return json.dumps(o, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

    def _hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _find_active_key_by_presented(api_keys, presented):
        # AUTH RULE: accept matching id OR matching key_prefix (client-visible) (never compare to hash with unknown plaintext)
        for r in api_keys:
            if r.get("status") == "active" and isinstance(presented, str) and presented and (presented == r.get("id") or presented == r.get("key_prefix")):
                return r
        return None

    def _get_day_window_start(now):
        return datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)

    def _get_or_create_counter(counters, api_key_id, window_start_iso):
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == "day" and c.get("window_start") == window_start_iso:
                return c
        c = {
            "id": _ulid(),
            "api_key_id": api_key_id,
            "window_start": window_start_iso,
            "window_type": "day",
            "requests_total": 0,
            "requests_succeeded": 0,
            "requests_failed": 0,
            "result_items_total": 0,
            "created_at": _iso(_now()),
            "updated_at": _iso(_now())
        }
        counters.append(c)
        return c

    def _token_bucket_allow(logs, api_key_row, now):
        # approximate token bucket: capacity=burst, refill=rps based on recent request timestamps
        rps = api_key_row.get("rate_limit_rps")
        burst = api_key_row.get("rate_limit_burst")
        if not (isinstance(rps, (int, float)) and rps > 0):
            return False, "INVALID_RATE_LIMIT"
        if not (isinstance(burst, int) and burst >= 1):
            return False, "INVALID_RATE_LIMIT"
        cutoff = now - datetime.timedelta(seconds=float(burst) / float(rps))
        recent = 0
        for lg in logs:
            if lg.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_dt(lg.get("created_at"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= burst:
            return False, "RATE_LIMIT"
        return True, None

    tool_name = "search_encyclopedia"
    t0 = time.time()
    now = _now()

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    response_cache = _load("response_cache.json")
    search_items = _load("search_result_items.json")
    usage_counters = _load("usage_counters.json")

    # Prepare request log skeleton (created early; may be updated to failed)
    req_id = _ulid()
    created_iso = _iso(now)

    # Validate basic types
    if not isinstance(api_key, str) or not api_key.strip():
        # log without api_key_id is not allowed by schema; return validation error without logging
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(keyword, str):
        return _err("VALIDATION_ERROR", "keyword must be a string")
    kw = keyword.strip()
    if not (1 <= len(kw) <= 255):
        return _err("VALIDATION_ERROR", "keyword length must be between 1 and 255 after trimming")

    if page is not None and (not isinstance(page, int) or page < 1):
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if display is not None and (not isinstance(display, int) or display < 1):
        return _err("VALIDATION_ERROR", "display must be an integer >= 1")
    if use_cache is not None and not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean")

    # Defaults
    dpy = 10 if display is None else display
    pg = 1 if page is None else page
    start = (pg - 1) * dpy + 1
    use_cache = True if use_cache is None else use_cache

    # Authenticate
    key_row = _find_active_key_by_presented(api_keys, api_key)
    if not key_row:
        # Cannot write request_logs without api_key_id; return unauthorized
        return _err("UNAUTHORIZED", "API key is invalid, inactive, or not authorized")

    # Rate limit (before creating request row outcome? Business says every invocation must create exactly one request_logs row.
    # We'll create row as received and then fail with RATE_LIMIT if exceeded.)
    can, why = _token_bucket_allow(request_logs, key_row, now)

    normalized_params = {
        "keyword": kw,
        "page": pg,
        "display": dpy,
        "start": start,
        "use_cache": use_cache
    }
    upstream_endpoint = "/v1/search/encyc.json"
    scope = {"api_key_id": key_row.get("id"), "naver_client_id": key_row.get("naver_client_id")}
    cache_key = _hash(tool_name + "|" + _stable_json(normalized_params) + "|" + _stable_json(scope))

    req_row = {
        "id": req_id,
        "api_key_id": key_row.get("id"),
        "tool_name": tool_name,
        "keyword": kw,
        "page": pg,
        "display": dpy,
        "start": start,
        "sort": None,
        "filter": None,
        "normalized_params": normalized_params,
        "cache_key": cache_key,
        "cache_hit": False,
        "status": "received",
        "upstream_endpoint": upstream_endpoint,
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "response_meta": None,
        "raw_response_ref": None,
        "result_items_count": 0,
        "duration_ms": None,
        "created_at": created_iso,
        "updated_at": created_iso
    }

    # Append request log immediately (received)
    request_logs.append(req_row)
    _save("request_logs.json", request_logs)

    def _update_req(fields):
        nonlocal req_row, request_logs
        req_row.update(fields)
        req_row["updated_at"] = _iso(_now())
        # persist update
        for i, r in enumerate(request_logs):
            if r.get("id") == req_id:
                request_logs[i] = req_row
                break
        _save("request_logs.json", request_logs)

    def _finalize(status, error_code=None, error_message=None, upstream_status=None, response_meta=None, cache_hit=False, items_count=0):
        duration_ms = max(0, int((time.time() - t0) * 1000))
        _update_req({
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "upstream_http_status": upstream_status,
            "response_meta": response_meta,
            "cache_hit": bool(cache_hit),
            "result_items_count": int(items_count),
            "duration_ms": duration_ms
        })
        # update usage counters
        day_start = _get_day_window_start(now)
        day_iso = _iso(day_start)
        ctr = _get_or_create_counter(usage_counters, key_row.get("id"), day_iso)
        # requests_total increments for every call logged
        ctr["requests_total"] = int(ctr.get("requests_total", 0)) + 1
        if status == "succeeded":
            ctr["requests_succeeded"] = int(ctr.get("requests_succeeded", 0)) + 1
        else:
            ctr["requests_failed"] = int(ctr.get("requests_failed", 0)) + 1
        ctr["result_items_total"] = int(ctr.get("result_items_total", 0)) + int(items_count if status == "succeeded" else 0)
        ctr["updated_at"] = _iso(_now())
        _save("usage_counters.json", usage_counters)

    # move to validated
    _update_req({"status": "validated"})

    # enforce rate limit
    if not can and why == "RATE_LIMIT":
        _finalize("failed", error_code="RATE_LIMIT", error_message="Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # enforce quota pre-upstream (requests_total +1 must not exceed quota_day_requests)
    day_iso = _iso(_get_day_window_start(now))
    ctr = _get_or_create_counter(usage_counters, key_row.get("id"), day_iso)
    quota_req = int(key_row.get("quota_day_requests", 0))
    quota_items = int(key_row.get("quota_day_results_items", 0))
    if int(ctr.get("requests_total", 0)) + 1 > quota_req:
        _finalize("failed", error_code="QUOTA_DAY_REQUESTS_EXCEEDED", error_message="Daily request quota exceeded")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_day_requests")
    # items quota checked after knowing items count; but we can pre-check worst-case? enforce at completion; for cache, enforce too.

    # cache lookup
    if use_cache:
        fresh = None
        for c in response_cache:
            if c.get("cache_key") == cache_key and c.get("tool_name") == tool_name and c.get("status") == "fresh":
                exp = _parse_dt(c.get("expires_at"))
                if exp and exp > now:
                    fresh = c
                    break
        if fresh:
            # serve from cache; no upstream
            _update_req({"status": "upstream_requested"})  # still track lifecycle
            # determine items: if items stored per request, we need to create new search_result_items for this request.
            # Since cache may not store items, we will not fabricate. We'll return 0 items unless items_ref exists and we can't deref.
            # Real backend might store items elsewhere; here, only allowed to return persisted rows. So return none unless we can copy from previous request by cache_key.
            items_to_copy = []
            # find a succeeded request with same cache_key and copy its items
            for r in request_logs:
                if r.get("cache_key") == cache_key and r.get("tool_name") == tool_name and r.get("status") == "succeeded":
                    src_id = r.get("id")
                    if src_id:
                        items_to_copy = [it for it in search_items if it.get("request_id") == src_id]
                    if items_to_copy:
                        break
            new_items = []
            if items_to_copy:
                for it in sorted(items_to_copy, key=lambda x: x.get("rank", 0)):
                    nit = dict(it)
                    nit["id"] = _ulid()
                    nit["request_id"] = req_id
                    nit["created_at"] = _iso(_now())
                    nit["updated_at"] = nit["created_at"]
                    new_items.append(nit)
                # quota check for items
                if int(ctr.get("result_items_total", 0)) + len(new_items) > quota_items:
                    _finalize("failed", error_code="QUOTA_DAY_RESULTS_ITEMS_EXCEEDED", error_message="Daily results items quota exceeded")
                    return _err("QUOTA_EXCEEDED", "Daily results items quota exceeded", quota="quota_day_results_items")
                search_items.extend(new_items)
                _save("search_result_items.json", search_items)

            meta = fresh.get("response_meta")
            _finalize("succeeded", upstream_status=200, response_meta=meta, cache_hit=True, items_count=len(new_items))
            return {
                "request": req_row,
                "meta": meta or {"cached": True},
                "items": sorted(new_items, key=lambda x: x.get("rank", 0)),
                "pagination": {"page": pg, "display": dpy, "start": start},
                "cache": {"hit": True, "cache_key": cache_key, "expires_at": fresh.get("expires_at")}
            }

    # "Upstream call" simulation: offline datastore service cannot reach Naver; create deterministic empty result with metadata.
    _update_req({"status": "upstream_requested"})

    # No fabricated items: return empty set; still can cache metadata
    response_meta = {
        "total": 0,
        "start": start,
        "display": dpy,
        "lastBuildDate": _iso(_now()),
        "upstream": {"endpoint": upstream_endpoint, "offline": True}
    }

    # items quota check with 0 items always passes
    # write cache entry (optional) with TTL 10 minutes
    if use_cache:
        ttl = datetime.timedelta(minutes=10)
        expires_at = _iso(now + ttl)
        # upsert unique(cache_key)
        existing = None
        for c in response_cache:
            if c.get("cache_key") == cache_key:
                existing = c
                break
        if existing:
            # transition allowed: fresh->stale/purged only, but we can refresh stale->fresh, fresh->fresh is idempotent
            if existing.get("status") == "purged":
                # cannot transition
                pass
            else:
                existing["tool_name"] = tool_name
                existing["normalized_params"] = normalized_params
                existing["status"] = "fresh"
                existing["response_meta"] = response_meta
                existing["raw_response_ref"] = None
                existing["items_ref"] = None
                existing["expires_at"] = expires_at
                existing["updated_at"] = _iso(_now())
        else:
            response_cache.append({
                "id": _ulid(),
                "cache_key": cache_key,
                "tool_name": tool_name,
                "normalized_params": normalized_params,
                "status": "fresh",
                "response_meta": response_meta,
                "raw_response_ref": None,
                "items_ref": None,
                "expires_at": expires_at,
                "created_at": _iso(_now()),
                "updated_at": _iso(_now())
            })
        _save("response_cache.json", response_cache)

    # finalize success
    # update api_keys last_used_at
    for i, k in enumerate(api_keys):
        if k.get("id") == key_row.get("id"):
            api_keys[i] = dict(k)
            api_keys[i]["last_used_at"] = _iso(_now())
            api_keys[i]["updated_at"] = _iso(_now())
            key_row = api_keys[i]
            break
    _save("api_keys.json", api_keys)

    _finalize("succeeded", upstream_status=200, response_meta=response_meta, cache_hit=False, items_count=0)
    return {
        "request": req_row,
        "meta": response_meta,
        "items": [],
        "pagination": {"page": pg, "display": dpy, "start": start},
        "cache": {"hit": False, "cache_key": cache_key}
    }

def search_cafe_article(api_key, keyword, page=None, display=None, sort=None, use_cache=None, **_extra):
