        "sort": srt,
        "filter": None,
        "normalized_params": normalized_params,
        "cache_key": cache_key,
        "cache_hit": False,
        "status": "received",
        "upstream_endpoint": upstream_endpoint,
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "response_meta": None,
        "raw_response_ref": None,
        "result_items_count": 0,
        "duration_ms": None,
        "created_at": created_iso,
        "updated_at": created_iso
    }
    request_logs.append(req_row)
    _save("request_logs.json", request_logs)

    def _update_req(fields):
        nonlocal req_row, request_logs
        req_row.update(fields)
        req_row["updated_at"] = _iso(_now())
        for i, r in enumerate(request_logs):
            if r.get("id") == req_id:
                request_logs[i] = req_row
                break
        _save("request_logs.json", request_logs)

    def _finalize(status, error_code=None, error_message=None, upstream_status=None, response_meta=None, cache_hit=False, items_count=0):
        duration_ms = max(0, int((time.time() - t0) * 1000))
        _update_req({
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "upstream_http_status": upstream_status,
            "response_meta": response_meta,
            "cache_hit": bool(cache_hit),
            "result_items_count": int(items_count),
            "duration_ms": duration_ms
        })
        day_start = _get_day_window_start(now)
        day_iso = _iso(day_start)
        ctr = _get_or_create_counter(usage_counters, key_row.get("id"), day_iso)
        ctr["requests_total"] = int(ctr.get("requests_total", 0)) + 1
        if status == "succeeded":
            ctr["requests_succeeded"] = int(ctr.get("requests_succeeded", 0)) + 1
        else:
            ctr["requests_failed"] = int(ctr.get("requests_failed", 0)) + 1
        ctr["result_items_total"] = int(ctr.get("result_items_total", 0)) + int(items_count if status == "succeeded" else 0)
        ctr["updated_at"] = _iso(_now())
        _save("usage_counters.json", usage_counters)

    _update_req({"status": "validated"})

    if not can and why == "RATE_LIMIT":
        _finalize("failed", error_code="RATE_LIMIT", error_message="Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    day_iso = _iso(_get_day_window_start(now))
    ctr = _get_or_create_counter(usage_counters, key_row.get("id"), day_iso)
    quota_req = int(key_row.get("quota_day_requests", 0))
    quota_items = int(key_row.get("quota_day_results_items", 0))
    if int(ctr.get("requests_total", 0)) + 1 > quota_req:
        _finalize("failed", error_code="QUOTA_DAY_REQUESTS_EXCEEDED", error_message="Daily request quota exceeded")
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_day_requests")

    if use_cache:
        fresh = None
        for c in response_cache:
            if c.get("cache_key") == cache_key and c.get("tool_name") == tool_name and c.get("status") == "fresh":
                exp = _parse_dt(c.get("expires_at"))
                if exp and exp > now:
                    fresh = c
                    break
        if fresh:
            _update_req({"status": "upstream_requested"})
            items_to_copy = []
            for r in request_logs:
                if r.get("cache_key") == cache_key and r.get("tool_name") == tool_name and r.get("status") == "succeeded":
                    src_id = r.get("id")
                    if src_id:
                        items_to_copy = [it for it in search_items if it.get("request_id") == src_id]
                    if items_to_copy:
                        break
            new_items = []
            if items_to_copy:
                for it in sorted(items_to_copy, key=lambda x: x.get("rank", 0)):
                    nit = dict(it)
                    nit["id"] = _ulid()
                    nit["request_id"] = req_id
                    nit["created_at"] = _iso(_now())
                    nit["updated_at"] = nit["created_at"]
                    new_items.append(nit)
                if int(ctr.get("result_items_total", 0)) + len(new_items) > quota_items:
                    _finalize("failed", error_code="QUOTA_DAY_RESULTS_ITEMS_EXCEEDED", error_message="Daily results items quota exceeded")
                    return _err("QUOTA_EXCEEDED", "Daily results items quota exceeded", quota="quota_day_results_items")
                search_items.extend(new_items)
                _save("search_result_items.json", search_items)
            meta = fresh.get("response_meta")
            _finalize("succeeded", upstream_status=200, response_meta=meta, cache_hit=True, items_count=len(new_items))
            return {
                "request": req_row,
                "meta": meta or {"cached": True},
                "items": sorted(new_items, key=lambda x: x.get("rank", 0)),
                "pagination": {"page": pg, "display": dpy, "start": st, "sort": srt},
                "cache": {"hit": True, "cache_key": cache_key, "expires_at": fresh.get("expires_at")}
            }

    _update_req({"status": "upstream_requested"})

    response_meta = {
        "total": 0,
        "start": st,
        "display": dpy,
        "sort": srt,
        "lastBuildDate": _iso(_now()),
        "upstream": {"endpoint": upstream_endpoint, "offline": True}
    }

    if use_cache:
        ttl = datetime.timedelta(minutes=10)
        expires_at = _iso(now + ttl)
        existing = None
        for c in response_cache:
            if c.get("cache_key") == cache_key:
                existing = c
                break
        if existing:
            if existing.get("status") != "purged":
                existing["tool_name"] = tool_name
                existing["normalized_params"] = normalized_params
                existing["status"] = "fresh"
                existing["response_meta"] = response_meta
                existing["raw_response_ref"] = None
                existing["items_ref"] = None
                existing["expires_at"] = expires_at
                existing["updated_at"] = _iso(_now())
        else:
            response_cache.append({
                "id": _ulid(),
                "cache_key": cache_key,
                "tool_name": tool_name,
                "normalized_params": normalized_params,
                "status": "fresh",
                "response_meta": response_meta,
                "raw_response_ref": None,
                "items_ref": None,
                "expires_at": expires_at,
                "created_at": _iso(_now()),
                "updated_at": _iso(_now())
            })
        _save("response_cache.json", response_cache)

    for i, k in enumerate(api_keys):
        if k.get("id") == key_row.get("id"):
            api_keys[i] = dict(k)
            api_keys[i]["last_used_at"] = _iso(_now())
            api_keys[i]["updated_at"] = _iso(_now())
            key_row = api_keys[i]
            break
    _save("api_keys.json", api_keys)

    _finalize("succeeded", upstream_status=200, response_meta=response_meta, cache_hit=False, items_count=0)
    return {
        "request": req_row,
        "meta": response_meta,
        "items": [],
        "pagination": {"page": pg, "display": dpy, "start": st, "sort": srt},
        "cache": {"hit": False, "cache_key": cache_key}
    }

def search_local(api_key, keyword, sort=None, display=None, start=None, use_cache=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0298000" if __import__("os").path.isdir("./environment_mix/0298000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulid():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        t = ms & ((1 << 48) - 1)
        out = []
        for _ in range(10):
            out.append(alphabet[t & 31])
            t >>= 5
        out = out[::-1]
        r = random.getrandbits(80)
        rand = []
        for _ in range(16):
            rand.append(alphabet[r & 31])
            r >>= 5
        return "".join(out + rand[::-1])

    def _stable_json(o):
        return json.dumps(o, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

    def _hash(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _find_active_key_by_presented(api_keys, presented):
        for r in api_keys:
            if r.get("status") == "active" and isinstance(presented, str) and presented and (presented == r.get("id") or presented == r.get("key_prefix")):
                return r
        return None

    def _get_day_window_start(now):
        return datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)

    def _get_or_create_counter(counters, api_key_id, window_start_iso):
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == "day" and c.get("window_start") == window_start_iso:
                return c
        c = {
            "id": _ulid(),
            "api_key_id": api_key_id,
            "window_start": window_start_iso,
            "window_type": "day",
            "requests_total": 0,
            "requests_succeeded": 0,
            "requests_failed": 0,
            "result_items_total": 0,
            "created_at": _iso(_now()),
            "updated_at": _iso(_now())
        }
        counters.append(c)
        return c

    def _token_bucket_allow(logs, api_key_row, now):
        rps = api_key_row.get("rate_limit_rps")
        burst = api_key_row.get("rate_limit_burst")
        if not (isinstance(rps, (int, float)) and rps > 0):
            return False, "INVALID_RATE_LIMIT"
        if not (isinstance(burst, int) and burst >= 1):
            return False, "INVALID_RATE_LIMIT"
        cutoff = now - datetime.timedelta(seconds=float(burst) / float(rps))
        recent = 0
        for lg in logs:
            if lg.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_dt(lg.get("created_at"))
            if ts and ts >= cutoff:
                recent += 1
        if recent >= burst:
            return False, "RATE_LIMIT"
        return True, None

    tool_name = "search_local"
    t0 = time.time()
    now = _now()

    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")
    response_cache = _load("response_cache.json")
    search_items = _load("search_result_items.json")
