    if st > 1:
        return _err("VALIDATION_ERROR", "start must be <= 1 for search_local")
    srt = "random" if sort is None else sort
    use_cache = True if use_cache is None else use_cache

    key_row = _find_active_key_by_presented(api_keys, api_key)
    if not key_row:
        return _err("UNAUTHORIZED", "API key is invalid, inactive, or not authorized")

    can, why = _token_bucket_allow(request_logs, key_row, now)

    normalized_params = {
        "keyword": kw,
        "display": dpy,
        "start": st,
        "sort": srt,
        "use_cache": use_cache
    }
    upstream_endpoint = "/v1/search/local.json"
    scope = {"api_key_id": key_row.get("id"), "naver_client_id": key_row.get("naver_client_id")}
    cache_key = _hash(tool_name + "|" + _stable_json(normalized_params) + "|" + _stable_json(scope))

    req_id = _ulid()
    created_iso = _iso(now)
    req_row = {
        "id": req_id,
        "api_key_id": key_row.get("id"),
        "tool_name": tool_name,
        "keyword": kw,
        "page": None,
        "display": dpy,
        "start": st,
        "sort": srt,
        "filter": None,
        "normalized_params": normalized_params,
        "cache_key": cache_key,
        "cache_hit": False,
        "status": "received",
        "upstream_endpoint": upstream_endpoint,
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "response_meta": None,
        "raw_response_ref": None,
