        author = f"저자{(seed + i_rank) % 50}"
        pub = datetime.datetime(2010 + ((seed + i_rank) % 15), ((i_rank - 1) % 12) + 1, ((i_rank - 1) % 28) + 1, tzinfo=datetime.timezone.utc)
        raw = {
            "title": title,
            "link": link,
            "description": desc,
            "author": author,
            "pubDate": _iso(pub),
        }
        return {
            "id": _ulid(),
            "request_id": req_id,
            "tool_name": "search_doc",
            "rank": i_rank,
            "title": title,
            "description": desc,
            "link_url": link,
            "thumbnail_url": None,
            "publisher_or_source": None,
            "author": author,
            "pub_date": _iso(pub),
            "price": None,
            "category": None,
            "address": None,
            "telephone": None,
            "raw_item": raw,
            "created_at": _iso(_now()),
            "updated_at": _iso(_now()),
        }

    produced = [_mk_item(rnk) for rnk in range(1, display + 1)]

    if u["result_items_total"] + len(produced) > quota_items:
