        "api_key_id": api_key_id,
        "tool_name": "search_image",
        "keyword": kw,
        "page": page,
        "display": display,
        "start": start,
        "sort": sort,
        "filter": filter,
        "normalized_params": normalized_params,
        "cache_key": cache_key,
        "cache_hit": False,
        "status": "received",
        "upstream_endpoint": "/v1/search/image.json",
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "response_meta": None,
        "raw_response_ref": None,
        "result_items_count": 0,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    if key_row.get("status") != "active":
        req_row["status"] = "failed"
        req_row["error_code"] = "API_KEY_INACTIVE"
        req_row["error_message"] = "API key is not active"
        req_row["updated_at"] = _iso(_now())
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        logs_rows.append(req_row)
        win_start = _iso(_day_window_start(now_dt))
        u = _get_or_create_usage(usage_rows, api_key_id, win_start)
        u["requests_total"] += 1
        u["requests_failed"] += 1
        u["updated_at"] = _iso(_now())
        _save("request_logs.json", logs_rows)
        _save("usage_counters.json", usage_rows)
        return _err("UNAUTHORIZED", "API key is not active")

    ok_rl, rl_err = _rate_limit_check_and_consume(key_row, logs_rows, api_key_id, now_dt)
    if not ok_rl:
        req_row["status"] = "failed"
        req_row["error_code"] = "RATE_LIMIT"
        req_row["error_message"] = rl_err["error"]["message"]
        req_row["updated_at"] = _iso(_now())
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        logs_rows.append(req_row)
        win_start = _iso(_day_window_start(now_dt))
        u = _get_or_create_usage(usage_rows, api_key_id, win_start)
        u["requests_total"] += 1
        u["requests_failed"] += 1
        u["updated_at"] = _iso(_now())
        _save("request_logs.json", logs_rows)
        _save("usage_counters.json", usage_rows)
        return rl_err

    win_start = _iso(_day_window_start(now_dt))
    u = _get_or_create_usage(usage_rows, api_key_id, win_start)
    quota_req = key_row.get("quota_day_requests")
    quota_items = key_row.get("quota_day_results_items")
    if not isinstance(quota_req, int) or quota_req < 0:
        return _err("VALIDATION_ERROR", "Invalid quota_day_requests on key")
    if not isinstance(quota_items, int) or quota_items < 0:
        return _err("VALIDATION_ERROR", "Invalid quota_day_results_items on key")

    if u["requests_total"] + 1 > quota_req:
        req_row["status"] = "failed"
        req_row["error_code"] = "QUOTA_DAY_REQUESTS_EXCEEDED"
        req_row["error_message"] = "Daily request quota exceeded"
        req_row["updated_at"] = _iso(_now())
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        logs_rows.append(req_row)
        u["requests_total"] += 1
        u["requests_failed"] += 1
        u["updated_at"] = _iso(_now())
        _save("request_logs.json", logs_rows)
        _save("usage_counters.json", usage_rows)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_day_requests")

    req_row["status"] = "validated"
    req_row["updated_at"] = _iso(_now())

    cache_entry = None
    cached_items = []
    if use_cache:
        for c in cache_rows:
            if c.get("cache_key") == cache_key and c.get("tool_name") == "search_image":
                if c.get("status") == "fresh":
                    exp = _parse_dt(c.get("expires_at"))
                    if exp and exp > now_dt:
                        cache_entry = c
                break
        if cache_entry is not None:
            cand = [r for r in logs_rows if r.get("tool_name") == "search_image" and r.get("cache_key") == cache_key and r.get("status") == "succeeded"]
            def _rt(r):
                return _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            cand.sort(key=_rt, reverse=True)
            if cand:
                cached_items = [it for it in items_rows if it.get("request_id") == cand[0].get("id")]
            if cache_entry is not None and not cached_items:
                cache_entry = None

    if cache_entry is not None:
        would_add_items = len(cached_items)
        if u["result_items_total"] + would_add_items > quota_items:
            req_row["status"] = "failed"
            req_row["error_code"] = "QUOTA_DAY_RESULTS_ITEMS_EXCEEDED"
            req_row["error_message"] = "Daily result items quota exceeded"
            req_row["updated_at"] = _iso(_now())
            req_row["duration_ms"] = int((time.time() - t0) * 1000)
            logs_rows.append(req_row)
            u["requests_total"] += 1
            u["requests_failed"] += 1
            u["updated_at"] = _iso(_now())
            _save("request_logs.json", logs_rows)
            _save("usage_counters.json", usage_rows)
            return _err("QUOTA_EXCEEDED", "Daily result items quota exceeded", quota="quota_day_results_items")

        req_row["cache_hit"] = True
        req_row["status"] = "succeeded"
        req_row["response_meta"] = cache_entry.get("response_meta") or {}
        req_row["updated_at"] = _iso(_now())
        req_row["duration_ms"] = int((time.time() - t0) * 1000)

        new_items = []
        for it in sorted(cached_items, key=lambda x: x.get("rank") or 0):
            new_it = dict(it)
            new_it["id"] = _ulid()
            new_it["request_id"] = req_id
            new_it["created_at"] = _iso(_now())
            new_it["updated_at"] = new_it["created_at"]
            new_items.append(new_it)
        items_rows.extend(new_items)
        req_row["result_items_count"] = len(new_items)

        logs_rows.append(req_row)
        u["requests_total"] += 1
        u["requests_succeeded"] += 1
        u["result_items_total"] += len(new_items)
        u["updated_at"] = _iso(_now())

        key_row["last_used_at"] = _iso(_now())
        key_row["updated_at"] = _iso(_now())

        _save("search_result_items.json", items_rows)
        _save("request_logs.json", logs_rows)
        _save("usage_counters.json", usage_rows)
        _save("api_keys.json", api_keys_rows)

        return {
            "request": req_row,
            "meta": req_row["response_meta"] or {},
            "items": new_items,
            "pagination": {"page": page, "display": display, "start": start},
            "cache": {"hit": True, "cache_key": cache_key, "expires_at": cache_entry.get("expires_at")},
        }

    req_row["status"] = "upstream_requested"
    req_row["updated_at"] = _iso(_now())

    seed = int(hashlib.sha256((cache_key + "|items").encode("utf-8")).hexdigest()[:16], 16)
    rnd = random.Random(seed)
    total = 90000 + (seed % 50000)

    size_dim = {"all": (800, 600), "small": (320, 240), "medium": (640, 480), "large": (1920, 1080)}[filter]

    def _mk_item(i_rank):
        w, h = size_dim
        # vary a bit
        ww = w + (i_rank * 13) % 97
        hh = h + (i_rank * 7) % 61
        img_id = f"{seed % 1000000:06d}{i_rank:03d}"
        link = f"https://images.naver.com/view/{img_id}"
        thumb = f"https://phinf.pstatic.net/{img_id}/thumb.jpg"
        title = f"{kw} 이미지 {i_rank}"
        source = f"출처{(seed + i_rank) % 31}"
        raw = {
            "title": title,
            "link": link,
            "thumbnail": thumb,
            "sizewidth": str(ww),
            "sizeheight": str(hh),
            "sort": sort,
            "filter": filter,
            "source": source,
        }
        return {
            "id": _ulid(),
            "request_id": req_id,
            "tool_name": "search_image",
            "rank": i_rank,
            "title": title,
            "description": None,
            "link_url": link,
            "thumbnail_url": thumb,
            "publisher_or_source": source,
            "author": None,
            "pub_date": None,
            "price": None,
            "category": None,
            "address": None,
            "telephone": None,
            "raw_item": raw,
            "created_at": _iso(_now()),
            "updated_at": _iso(_now()),
        }

    produced = [_mk_item(rnk) for rnk in range(1, display + 1)]

    if u["result_items_total"] + len(produced) > quota_items:
        req_row["status"] = "failed"
        req_row["error_code"] = "QUOTA_DAY_RESULTS_ITEMS_EXCEEDED"
        req_row["error_message"] = "Daily result items quota exceeded"
        req_row["updated_at"] = _iso(_now())
        req_row["duration_ms"] = int((time.time() - t0) * 1000)
        logs_rows.append(req_row)
        u["requests_total"] += 1
        u["requests_failed"] += 1
        u["updated_at"] = _iso(_now())
        _save("request_logs.json", logs_rows)
        _save("usage_counters.json", usage_rows)
        return _err("QUOTA_EXCEEDED", "Daily result items quota exceeded", quota="quota_day_results_items")

    items_rows.extend(produced)

    response_meta = {
        "total": total,
        "start": start,
        "display": display,
        "lastBuildDate": _iso(_now()),
        "sort": sort,
        "filter": filter,
    }

    req_row["status"] = "succeeded"
    req_row["upstream_http_status"] = 200
    req_row["response_meta"] = response_meta
    req_row["result_items_count"] = len(produced)
    req_row["updated_at"] = _iso(_now())
    req_row["duration_ms"] = int((time.time() - t0) * 1000)

    if use_cache:
        ttl_seconds = 600
        expires_at = _iso(now_dt + datetime.timedelta(seconds=ttl_seconds))
        existing = next((c for c in cache_rows if c.get("cache_key") == cache_key), None)
        if existing:
            existing["tool_name"] = "search_image"
            existing["normalized_params"] = normalized_params
            existing["status"] = "fresh"
            existing["response_meta"] = response_meta
            existing["raw_response_ref"] = None
            existing["items_ref"] = None
            existing["expires_at"] = expires_at
            existing["updated_at"] = _iso(_now())
        else:
            cache_rows.append({
                "id": _ulid(),
                "cache_key": cache_key,
                "tool_name": "search_image",
                "normalized_params": normalized_params,
                "status": "fresh",
                "response_meta": response_meta,
                "raw_response_ref": None,
                "items_ref": None,
                "expires_at": expires_at,
                "created_at": _iso(_now()),
                "updated_at": _iso(_now()),
            })

    logs_rows.append(req_row)
    u["requests_total"] += 1
    u["requests_succeeded"] += 1
    u["result_items_total"] += len(produced)
    u["updated_at"] = _iso(_now())

    key_row["last_used_at"] = _iso(_now())
    key_row["updated_at"] = _iso(_now())

    _save("search_result_items.json", items_rows)
    _save("request_logs.json", logs_rows)
    _save("usage_counters.json", usage_rows)
    _save("response_cache.json", cache_rows)
    _save("api_keys.json", api_keys_rows)

    return {
        "request": req_row,
        "meta": response_meta,
        "items": produced,
        "pagination": {"page": page, "display": display, "start": start},
        "cache": {"hit": False, "cache_key": cache_key},
    }

def whoami(api_key, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0298000" if __import__("os").path.isdir("./environment_mix/0298000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _TOOL = "whoami"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().replace(microsecond=0).isoformat()

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_CROCKFORD[t % 32])
            t //= 32
        time_part = "".join(reversed(chars))
        r = int.from_bytes(os.urandom(10), "big")
        chars = []
        for _ in range(16):
            chars.append(_CROCKFORD[r % 32])
            r //= 32
        rand_part = "".join(reversed(chars))
        return f"{prefix}{time_part}{rand_part}"

    def _stable_json(obj):
        return json.dumps(obj, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _parse_iso(dtstr):
        if dtstr is None:
            return None
        if isinstance(dtstr, datetime.datetime):
            return dtstr
        if not isinstance(dtstr, str) or not dtstr:
            return None
        try:
            return datetime.datetime.fromisoformat(dtstr.replace("Z", "+00:00"))
        except Exception:
            return None

    def _day_window_start(dt):
        d = dt.astimezone(datetime.timezone.utc).date()
        return datetime.datetime(d.year, d.month, d.day, tzinfo=datetime.timezone.utc)

    def _auth_api_key(presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        presented = presented.strip()
        keys = _load("api_keys.json")
        for r in keys:
            if r.get("id") == presented:
                return r
        for r in keys:
            if r.get("key_prefix") and presented.startswith(r.get("key_prefix")):
                return r
        return None

    def _ensure_usage_counter(counters, api_key_id, win_start_iso, now_iso):
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == "day" and c.get("window_start") == win_start_iso:
                return c
        row = {
            "id": _ulid_like("nvs_usg_"),
            "api_key_id": api_key_id,
            "window_start": win_start_iso,
            "window_type": "day",
            "requests_total": 0,
            "requests_succeeded": 0,
            "requests_failed": 0,
            "result_items_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        counters.append(row)
        return row

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing api_key.")

    t0 = time.time()
    now_dt = _now()
    now_iso = now_dt.replace(microsecond=0).isoformat()

    key_row = _auth_api_key(api_key)
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.", api_key_id=key_row.get("id"), status=key_row.get("status"))

    api_key_id = key_row.get("id")
    request_logs = _load("request_logs.json")
    usage_counters = _load("usage_counters.json")

    # log tool invocation (whoami has no keyword)
    normalized_params = {"api_key_id": api_key_id}
    cache_key = _sha256_hex(_TOOL + ":" + _stable_json(normalized_params))
    req_id = _ulid_like("nvs_req_")
    req_row = {
        "id": req_id,
        "api_key_id": api_key_id,
        "tool_name": _TOOL,
        "keyword": None,
        "page": None,
        "display": None,
        "start": None,
        "sort": None,
        "filter": None,
        "normalized_params": normalized_params,
        "cache_key": cache_key,
        "cache_hit": False,
        "status": "succeeded",
        "upstream_endpoint": None,
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "response_meta": None,
        "raw_response_ref": None,
        "result_items_count": 0,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    request_logs.append(req_row)

    # increment usage counters
    win_start = _day_window_start(now_dt).replace(microsecond=0).isoformat()
    usg = _ensure_usage_counter(usage_counters, api_key_id, win_start, now_iso)
    usg["requests_total"] += 1
    usg["requests_succeeded"] += 1
    usg["updated_at"] = now_iso

    # update last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    api_keys_all = _load("api_keys.json")
    for i, r in enumerate(api_keys_all):
        if r.get("id") == api_key_id:
            api_keys_all[i] = key_row
            break

    req_row["duration_ms"] = int((time.time() - t0) * 1000)
    req_row["updated_at"] = _now_iso()
    usg["updated_at"] = req_row["updated_at"]

    _save("api_keys.json", api_keys_all)
    _save("request_logs.json", request_logs)
    _save("usage_counters.json", usage_counters)

    return {
        "api_key_id": api_key_id,
        "status": key_row.get("status"),
        "name": key_row.get("name"),
        "owner": key_row.get("owner"),
        "naver_client_id": key_row.get("naver_client_id"),
        "limits": {
            "quota_day_requests": key_row.get("quota_day_requests"),
            "quota_day_results_items": key_row.get("quota_day_results_items"),
            "rate_limit_rps": key_row.get("rate_limit_rps"),
            "rate_limit_burst": key_row.get("rate_limit_burst"),
        },
        "usage_day_utc": {
            "window_start": win_start,
            "requests_total": usg.get("requests_total"),
            "requests_succeeded": usg.get("requests_succeeded"),
            "requests_failed": usg.get("requests_failed"),
            "result_items_total": usg.get("result_items_total"),
        },
        "request_log_id": req_id,
    }

def create_api_key(name, owner, naver_client_id, naver_client_secret, quota_day_requests, quota_day_results_items, rate_limit_rps, rate_limit_burst, status=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0298000" if __import__("os").path.isdir("./environment_mix/0298000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _ulid_like(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_CROCKFORD[t % 32])
            t //= 32
        time_part = "".join(reversed(chars))
        r = int.from_bytes(secrets.token_bytes(10), "big")
        chars = []
        for _ in range(16):
            chars.append(_CROCKFORD[r % 32])
            r //= 32
        rand_part = "".join(reversed(chars))
        return f"{prefix}{time_part}{rand_part}"

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    # ---- Validate inputs (match schema/business constraints; do not invent extra uniqueness rules) ----
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if not isinstance(owner, str) or not owner.strip():
        return _err("VALIDATION_ERROR", "owner must be a non-empty string.")
    if not isinstance(naver_client_id, str) or not naver_client_id.strip():
        return _err("VALIDATION_ERROR", "naver_client_id must be a non-empty string.")
    if not isinstance(naver_client_secret, str) or not naver_client_secret.strip():
        return _err("VALIDATION_ERROR", "naver_client_secret must be a non-empty string.")
    if not isinstance(quota_day_requests, int) or quota_day_requests < 0:
        return _err("VALIDATION_ERROR", "quota_day_requests must be an integer >= 0.")
    if not isinstance(quota_day_results_items, int) or quota_day_results_items < 0:
        return _err("VALIDATION_ERROR", "quota_day_results_items must be an integer >= 0.")

    # rate_limit_rps is "integer" in tool schema, but stored as number; accept int/float > 0
    if not isinstance(rate_limit_rps, (int, float)) or isinstance(rate_limit_rps, bool) or rate_limit_rps <= 0:
        return _err("VALIDATION_ERROR", "rate_limit_rps must be a number > 0.")
    if not isinstance(rate_limit_burst, int) or rate_limit_burst < 1:
        return _err("VALIDATION_ERROR", "rate_limit_burst must be an integer >= 1.")

    if status is None:
        status = "active"
    if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked.")

    nm = name.strip()
    ow = owner.strip()
    cid = naver_client_id.strip()

    # ---- Load existing keys ----
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    # ---- Enforce ONLY declared uniqueness constraints: unique(key_hash), unique(key_prefix) ----
    # Generate a plaintext key once; store only hash/prefix.
    # Ensure prefix uniqueness by regenerating if collision (extremely unlikely, but required by constraint).
    plaintext = None
    key_hash = None
    key_prefix = None
    for _ in range(20):
        # client-visible API key value; allow authenticating by id OR this plaintext (per ambient auth rule)
        candidate = "nvs_live_" + secrets.token_urlsafe(24)
        cand_hash = _sha256_hex(candidate)
        cand_prefix = candidate[:8]
        if any((row.get("key_hash") == cand_hash or row.get("key_prefix") == cand_prefix) for row in api_keys if isinstance(row, dict)):
            continue
        plaintext, key_hash, key_prefix = candidate, cand_hash, cand_prefix
        break
    if plaintext is None:
        return _err("CONFLICT", "Could not allocate a unique api key (key_prefix/key_hash collision).")

    now = _now().isoformat()
    new_id = _ulid_like("nvs_key_")

    row = {
        "id": new_id,
        "key_hash": key_hash,
        "key_prefix": key_prefix,
        "name": nm,
        "owner": ow,
        "status": status,
        "naver_client_id": cid,
        "naver_client_secret_ref": naver_client_secret.strip(),  # store as ref; never returned
        "quota_day_requests": int(quota_day_requests),
        "quota_day_results_items": int(quota_day_results_items),
        "rate_limit_rps": float(rate_limit_rps),
        "rate_limit_burst": int(rate_limit_burst),
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }

    api_keys.append(row)
    _save("api_keys.json", api_keys)

    # Return entity + plaintext key once
    entity = dict(row)
    return {"api_key": plaintext, "api_key_entity": entity}

def list_api_keys(api_key, owner=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0298000" if __import__("os").path.isdir("./environment_mix/0298000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _TOOL = "list_api_keys"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _parse_iso(dtstr):
        if dtstr is None:
            return None
        if isinstance(dtstr, datetime.datetime):
            return dtstr
        if not isinstance(dtstr, str) or not dtstr:
            return None
        try:
            return datetime.datetime.fromisoformat(dtstr.replace("Z", "+00:00"))
        except Exception:
            return None

    def _encode_cursor(payload):
        raw = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _ulid_like(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_CROCKFORD[t % 32])
            t //= 32
        time_part = "".join(reversed(chars))
        r = int.from_bytes(os.urandom(10), "big")
        chars = []
        for _ in range(16):
            chars.append(_CROCKFORD[r % 32])
            r //= 32
        rand_part = "".join(reversed(chars))
        return f"{prefix}{time_part}{rand_part}"

    def _stable_json(obj):
        return json.dumps(obj, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _auth_api_key(presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        presented = presented.strip()
        keys = _load("api_keys.json")
        for r in keys:
            if r.get("id") == presented:
                return r
        for r in keys:
            if r.get("key_prefix") and presented.startswith(r.get("key_prefix")):
                return r
        return None

    # Validate (accept floats passed by some clients, coercing if integral)
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("UNAUTHORIZED", "Missing api_key.")
    if owner is not None and not isinstance(owner, str):
        return _err("VALIDATION_ERROR", "owner must be a string.")
    if status is not None and status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked.")
    if limit is None:
        limit = 50
    if isinstance(limit, float) and limit.is_integer():
        limit = int(limit)
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sort is None:
        sort = "created_at_desc"
    if sort not in ("created_at_desc", "created_at_asc", "last_used_at_desc"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at_desc, created_at_asc, last_used_at_desc.")

    # Authenticate
    caller = _auth_api_key(api_key)
    if caller is None:
        return _err("UNAUTHORIZED", "Invalid api_key.")
    if caller.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.", api_key_id=caller.get("id"), status=caller.get("status"))

    # Log invocation (required)
    request_logs = _load("request_logs.json")
    normalized_params = {"owner": owner, "status": status, "limit": limit, "cursor": cursor, "sort": sort}
    cache_key = _sha256_hex(_TOOL + ":" + _stable_json(normalized_params))
    now = _now_iso()
    req_row = {
        "id": _ulid_like("nvs_req_"),
        "api_key_id": caller.get("id"),
        "tool_name": _TOOL,
        "keyword": None,
        "page": None,
        "display": None,
        "start": None,
        "sort": None,
        "filter": None,
        "normalized_params": normalized_params,
        "cache_key": cache_key,
        "cache_hit": False,
        "status": "succeeded",
        "upstream_endpoint": None,
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "response_meta": None,
        "raw_response_ref": None,
        "result_items_count": 0,
        "duration_ms": 0,
        "created_at": now,
        "updated_at": now,
    }
    request_logs.append(req_row)
    _save("request_logs.json", request_logs)

    keys = _load("api_keys.json")

    # Visibility: keys for same owner as caller by default; if owner filter provided, must match caller owner
    caller_owner = caller.get("owner")
    if owner is None:
        owner_eff = caller_owner
    else:
        owner_eff = owner
        if caller_owner is not None and owner_eff != caller_owner:
            # no permission model in schema; treat as unauthorized to view other owners
            return _err("UNAUTHORIZED", "Not authorized to list API keys for the requested owner.")

    rows = []
    for r in keys:
        if owner_eff is not None and (r.get("owner") or None) != owner_eff:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    # Sorting
    def _sort_key(r):
        if sort == "created_at_desc":
            dt = _parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (-dt.timestamp(), r.get("id") or "")
        if sort == "created_at_asc":
            dt = _parse_iso(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt.timestamp(), r.get("id") or "")
        # last_used_at_desc
        dt = _parse_iso(r.get("last_used_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (-dt.timestamp(), r.get("id") or "")

    rows.sort(key=_sort_key)

    # Cursor: accept either an encoded cursor (preferred) or an api_key id (legacy)
    start_index = 0
    if cursor:
        decoded = _decode_cursor(cursor)
        if isinstance(decoded, dict) and decoded.get("after_id"):
            after_id = decoded.get("after_id")
            for i, r in enumerate(rows):
                if r.get("id") == after_id:
                    start_index = i + 1
                    break
        else:
            # treat cursor as an id directly
            for i, r in enumerate(rows):
                if r.get("id") == cursor:
                    start_index = i + 1
                    break

    page_rows = rows[start_index:start_index + limit]
    has_more = (start_index + limit) < len(rows)
    next_cursor = None
    if has_more and page_rows:
        next_cursor = _encode_cursor({"after_id": page_rows[-1].get("id"), "sort": sort, "owner": owner_eff, "status": status})

    # Remove any secret-like fields (keep key_prefix)
    out = []
    for r in page_rows:
        rr = dict(r)
        rr.pop("key_hash", None)
        rr.pop("naver_client_secret_ref", None)
        out.append(rr)

    return {"data": out, "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def update_api_key(api_key, id, name=None, owner=None, status=None, quota_day_requests=None, quota_day_results_items=None, rate_limit_rps=None, rate_limit_burst=None, naver_client_id=None, naver_client_secret=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0298000" if __import__("os").path.isdir("./environment_mix/0298000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    # Minimal ULID-like generator (time-ordered-ish), sufficient for local datastore ids
    def _new_id():
        ts = int(time.time() * 1000)
        rand = secrets.token_hex(10)
        return f"01{ts:010d}{rand}"[:26]

    def _parse_bool(v):
        if isinstance(v, bool) or v is None:
            return v
        return None

    def _ensure_int(v, field, minv=None, maxv=None):
        if v is None:
            return (True, None)
        if not isinstance(v, int) or isinstance(v, bool):
            return (False, _err("VALIDATION_ERROR", f"{field} must be an integer"))
        if minv is not None and v < minv:
            return (False, _err("VALIDATION_ERROR", f"{field} must be >= {minv}"))
        if maxv is not None and v > maxv:
            return (False, _err("VALIDATION_ERROR", f"{field} must be <= {maxv}"))
        return (True, v)

    def _ensure_number(v, field, minv=None):
        if v is None:
            return (True, None)
        if not isinstance(v, (int, float)) or isinstance(v, bool):
            return (False, _err("VALIDATION_ERROR", f"{field} must be a number"))
        if minv is not None and v <= minv:
            return (False, _err("VALIDATION_ERROR", f"{field} must be > {minv}"))
        return (True, float(v))

    def _key_hash_presented(k):
        # Service stores key_hash; we must authenticate by comparing the presented value
        # to a deterministic hash computed the same way. Use SHA256 of the presented key.
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _authenticate(presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        presented = presented.strip()
        keys = _load("api_keys.json")
        # Try match by id (client-visible) OR by stored prefix OR by computed hash
        ph = _key_hash_presented(presented)
        for row in keys:
            if row.get("id") == presented:
                return row
        for row in keys:
            if row.get("key_prefix") and presented.startswith(row.get("key_prefix")):
                # prefix is non-secret; don't authenticate solely on prefix
                continue
        for row in keys:
            if row.get("key_hash") == ph:
                return row
        return None

    def _log_call(api_key_row, status_val, error_code=None, error_message=None, duration_ms=None):
        # This endpoint isn't in the request_logs.tool_name enum.
        # Still must record service dynamics: we record under request_logs with tool_name='correct_errata'
        # but tag the actual operation in normalized_params._internal_tool.
        logs = _load("request_logs.json")
        now = _now_iso()
        log_row = {
            "id": _new_id(),
            "api_key_id": api_key_row.get("id") if api_key_row else "unknown",
            "tool_name": "correct_errata",
            "keyword": None,
            "page": None,
            "display": None,
            "start": None,
            "sort": None,
            "filter": None,
            "normalized_params": {"_internal_tool": "update_api_key", "target_id": id},
            "cache_key": hashlib.sha256(f"update_api_key:{id}".encode("utf-8")).hexdigest(),
            "cache_hit": False,
            "status": status_val,
            "upstream_endpoint": None,
            "upstream_http_status": None,
            "error_code": error_code,
            "error_message": error_message,
            "response_meta": None,
            "raw_response_ref": None,
            "result_items_count": 0,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(log_row)
        _save("request_logs.json", logs)

        # usage counters: counts all calls
        counters = _load("usage_counters.json")
        if api_key_row and api_key_row.get("id"):
            nowdt = datetime.datetime.now(datetime.timezone.utc)
            window_start = nowdt.replace(hour=0, minute=0, second=0, microsecond=0).isoformat()
            c = None
            for row in counters:
                if row.get("api_key_id") == api_key_row["id"] and row.get("window_type") == "day" and row.get("window_start") == window_start:
                    c = row
                    break
            if c is None:
                c = {
                    "id": _new_id(),
                    "api_key_id": api_key_row["id"],
                    "window_start": window_start,
                    "window_type": "day",
                    "requests_total": 0,
                    "requests_succeeded": 0,
                    "requests_failed": 0,
                    "result_items_total": 0,
                    "created_at": now,
                    "updated_at": now,
                }
                counters.append(c)
            c["requests_total"] = int(c.get("requests_total", 0)) + 1
            if status_val == "succeeded":
                c["requests_succeeded"] = int(c.get("requests_succeeded", 0)) + 1
            elif status_val == "failed":
                c["requests_failed"] = int(c.get("requests_failed", 0)) + 1
            c["updated_at"] = now
            _save("usage_counters.json", counters)

    t0 = time.time()

    # Validate required
    if not isinstance(api_key, str) or not api_key.strip():
        # can't log without auth context
        return _err("UNAUTHORIZED", "Missing or invalid api_key")
    if not isinstance(id, str) or not id.strip():
        ar = _authenticate(api_key)
        if ar:
            _log_call(ar, "failed", error_code="VALIDATION_ERROR", error_message="id is required", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "id is required")

    caller = _authenticate(api_key)
    if caller is None or caller.get("status") != "active":
        # no valid combination in store
        return _err("UNAUTHORIZED", "Invalid API key or inactive key")

    # Validate optional fields
    if name is not None and (not isinstance(name, str) or len(name) > 200):
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="name must be a string up to 200 chars", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "name must be a string up to 200 chars")
    if owner is not None and (not isinstance(owner, str) or len(owner) > 200):
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="owner must be a string up to 200 chars", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "owner must be a string up to 200 chars")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
            _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="Invalid status", duration_ms=int((time.time()-t0)*1000))
            return _err("VALIDATION_ERROR", "Invalid status")

    ok, v = _ensure_int(quota_day_requests, "quota_day_requests", minv=0)
    if not ok:
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message=v["error"]["message"], duration_ms=int((time.time()-t0)*1000))
        return v
    quota_day_requests = v

    ok, v = _ensure_int(quota_day_results_items, "quota_day_results_items", minv=0)
    if not ok:
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message=v["error"]["message"], duration_ms=int((time.time()-t0)*1000))
        return v
    quota_day_results_items = v

    # Tool says rate_limit_rps is integer, schema says number>0
    if rate_limit_rps is not None:
        if not isinstance(rate_limit_rps, int) or isinstance(rate_limit_rps, bool) or rate_limit_rps <= 0:
            _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="rate_limit_rps must be an integer > 0", duration_ms=int((time.time()-t0)*1000))
            return _err("VALIDATION_ERROR", "rate_limit_rps must be an integer > 0")
        rate_limit_rps = float(rate_limit_rps)

    ok, v = _ensure_int(rate_limit_burst, "rate_limit_burst", minv=1)
    if not ok:
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message=v["error"]["message"], duration_ms=int((time.time()-t0)*1000))
        return v
    rate_limit_burst = v

    if naver_client_id is not None and (not isinstance(naver_client_id, str) or not naver_client_id.strip()):
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="naver_client_id must be a non-empty string", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "naver_client_id must be a non-empty string")
    if naver_client_secret is not None and (not isinstance(naver_client_secret, str) or not naver_client_secret.strip()):
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="naver_client_secret must be a non-empty string", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "naver_client_secret must be a non-empty string")

    keys = _load("api_keys.json")
    target = None
    for row in keys:
        if row.get("id") == id:
            target = row
            break
    if target is None:
        _log_call(caller, "failed", error_code="NOT_FOUND", error_message="api_keys row not found", duration_ms=int((time.time()-t0)*1000))
        return _err("NOT_FOUND", "API key not found")

    # Authorization: allow only updating itself (common pattern)
    if caller.get("id") != target.get("id"):
        _log_call(caller, "failed", error_code="UNAUTHORIZED", error_message="Not authorized to update this API key", duration_ms=int((time.time()-t0)*1000))
        return _err("UNAUTHORIZED", "Not authorized to update this API key")

    # Lifecycle transition validation
    if status is not None and status != target.get("status"):
        transitions = {
            "active": {"suspended", "revoked"},
            "suspended": {"active", "revoked"},
            "revoked": set(),
        }
        cur = target.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _log_call(caller, "failed", error_code="INVALID_TRANSITION", error_message=f"Cannot transition status from {cur} to {status}", duration_ms=int((time.time()-t0)*1000))
            return _err("INVALID_TRANSITION", f"Cannot transition status from {cur} to {status}")

    # Apply updates
    changed = False
    now = _now_iso()

    def _set(field, val):
        nonlocal changed
        if val is None:
            return
        if target.get(field) != val:
            target[field] = val
            changed = True

    _set("name", name)
    _set("owner", owner)
    _set("status", status)
    if quota_day_requests is not None:
        _set("quota_day_requests", quota_day_requests)
    if quota_day_results_items is not None:
        _set("quota_day_results_items", quota_day_results_items)
    if rate_limit_rps is not None:
        _set("rate_limit_rps", float(rate_limit_rps))
    if rate_limit_burst is not None:
        _set("rate_limit_burst", rate_limit_burst)
    _set("naver_client_id", naver_client_id)

    if naver_client_secret is not None:
        # store only a reference
        ref = f"secretref:{hashlib.sha256((target.get('id','') + ':' + naver_client_secret.strip()).encode('utf-8')).hexdigest()}"
        _set("naver_client_secret_ref", ref)

    if not changed:
        # idempotent update, but still a real call; succeed returning current entity
        target["updated_at"] = target.get("updated_at") or now
        _save("api_keys.json", keys)
        caller["last_used_at"] = now
        caller["updated_at"] = now
        _save("api_keys.json", keys)
        _log_call(caller, "succeeded", duration_ms=int((time.time()-t0)*1000))
    else:
        target["updated_at"] = now
        # update caller last_used_at too (same row)
        target["last_used_at"] = now
        _save("api_keys.json", keys)
        _log_call(target, "succeeded", duration_ms=int((time.time()-t0)*1000))

    # Never return secret ref? schema allows returning it but tool says never returns stored raw secret payloads;
    # We'll return entity with naver_client_secret_ref included but not secret.
    resp = dict(target)
    return {"api_key": resp}

def list_request_logs(api_key, api_key_id=None, tool_name=None, status=None, keyword=None, cache_hit=None, from_created_at=None, to_created_at=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0298000" if __import__("os").path.isdir("./environment_mix/0298000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat()

    def _new_id():
        ts = int(time.time() * 1000)
        rand = secrets.token_hex(10)
        return f"01{ts:010d}{rand}"[:26]

    def _key_hash_presented(k):
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _authenticate(presented):
        if not isinstance(presented, str) or not presented.strip():
            return None
        presented = presented.strip()
        keys = _load("api_keys.json")
        ph = _key_hash_presented(presented)
        for row in keys:
            if row.get("id") == presented:
                return row
        for row in keys:
            if row.get("key_hash") == ph:
                return row
        return None

    def _parse_dt(s, field):
        if s is None:
            return (True, None)
        if not isinstance(s, str) or not s.strip():
            return (False, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 timestamp string"))
        s = s.strip()
        try:
            # accept trailing Z
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return (True, dt.astimezone(datetime.timezone.utc))
        except Exception:
            return (False, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 timestamp string"))

    def _log_call(api_key_row, status_val, error_code=None, error_message=None, duration_ms=None):
        logs = _load("request_logs.json")
        now = _now_iso()
        log_row = {
            "id": _new_id(),
            "api_key_id": api_key_row.get("id") if api_key_row else "unknown",
            "tool_name": "correct_errata",
            "keyword": None,
            "page": None,
            "display": None,
            "start": None,
            "sort": None,
            "filter": None,
            "normalized_params": {"_internal_tool": "list_request_logs"},
            "cache_key": hashlib.sha256(f"list_request_logs:{api_key_row.get('id','unknown')}".encode("utf-8")).hexdigest(),
            "cache_hit": False,
            "status": status_val,
            "upstream_endpoint": None,
            "upstream_http_status": None,
            "error_code": error_code,
            "error_message": error_message,
            "response_meta": None,
            "raw_response_ref": None,
            "result_items_count": 0,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(log_row)
        _save("request_logs.json", logs)

        counters = _load("usage_counters.json")
        if api_key_row and api_key_row.get("id"):
            nowdt = datetime.datetime.now(datetime.timezone.utc)
            window_start = nowdt.replace(hour=0, minute=0, second=0, microsecond=0).isoformat()
            c = None
            for row in counters:
                if row.get("api_key_id") == api_key_row["id"] and row.get("window_type") == "day" and row.get("window_start") == window_start:
                    c = row
                    break
            if c is None:
                c = {
                    "id": _new_id(),
                    "api_key_id": api_key_row["id"],
                    "window_start": window_start,
                    "window_type": "day",
                    "requests_total": 0,
                    "requests_succeeded": 0,
                    "requests_failed": 0,
                    "result_items_total": 0,
                    "created_at": now,
                    "updated_at": now,
                }
                counters.append(c)
            c["requests_total"] = int(c.get("requests_total", 0)) + 1
            if status_val == "succeeded":
                c["requests_succeeded"] = int(c.get("requests_succeeded", 0)) + 1
            elif status_val == "failed":
                c["requests_failed"] = int(c.get("requests_failed", 0)) + 1
            c["updated_at"] = now
            _save("usage_counters.json", counters)

    t0 = time.time()

    caller = _authenticate(api_key)
    if caller is None or caller.get("status") != "active":
        return _err("UNAUTHORIZED", "Invalid API key or inactive key")

    # validate filters
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="api_key_id must be a non-empty string", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string")

    allowed_tool = {
        "search_blog","search_news","search_book","search_encyclopedia","search_cafe_article","search_kin",
        "search_local","search_shop","search_doc","search_image","search_webkr","correct_errata","check_adult_query"
    }
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in allowed_tool:
            _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="Invalid tool_name", duration_ms=int((time.time()-t0)*1000))
            return _err("VALIDATION_ERROR", "Invalid tool_name")

    allowed_status = {"received","validated","upstream_requested","succeeded","failed"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="Invalid status", duration_ms=int((time.time()-t0)*1000))
            return _err("VALIDATION_ERROR", "Invalid status")

    if keyword is not None:
        if not isinstance(keyword, str):
            _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="keyword must be a string", duration_ms=int((time.time()-t0)*1000))
            return _err("VALIDATION_ERROR", "keyword must be a string")
        keyword = keyword.strip()

    if cache_hit is not None and not isinstance(cache_hit, bool):
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="cache_hit must be a boolean", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "cache_hit must be a boolean")

    ok, fd = _parse_dt(from_created_at, "from_created_at")
    if not ok:
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message=fd["error"]["message"], duration_ms=int((time.time()-t0)*1000))
        return fd
    ok, td = _parse_dt(to_created_at, "to_created_at")
    if not ok:
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message=td["error"]["message"], duration_ms=int((time.time()-t0)*1000))
        return td
    if fd and td and fd >= td:
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="from_created_at must be before to_created_at", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "from_created_at must be before to_created_at")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 200:
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="limit must be an integer 1-200", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "limit must be an integer 1-200")

    if sort is None:
        sort = "created_at_desc"
    if not isinstance(sort, str) or sort not in ("created_at_desc", "created_at_asc"):
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="Invalid sort", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "Invalid sort")

    # Cursor is an opaque base: "<created_at>|<id>"
    if cursor is not None and (not isinstance(cursor, str) or "|" not in cursor):
        _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message="Invalid cursor", duration_ms=int((time.time()-t0)*1000))
        return _err("VALIDATION_ERROR", "Invalid cursor")
    cursor_created_at = None
    cursor_id = None
    if cursor:
        p = cursor.split("|", 1)
        ok, dtv = _parse_dt(p[0], "cursor.created_at")
        if not ok:
            _log_call(caller, "failed", error_code="VALIDATION_ERROR", error_message=dtv["error"]["message"], duration_ms=int((time.time()-t0)*1000))
            return dtv
        cursor_created_at = dtv
        cursor_id = p[1]

    # Authorization: allow viewing only own api_key_id unless caller matches filter
    if api_key_id is not None and api_key_id.strip() != caller.get("id"):
        _log_call(caller, "failed", error_code="UNAUTHORIZED", error_message="Not authorized to view logs for this api_key_id", duration_ms=int((time.time()-t0)*1000))
        return _err("UNAUTHORIZED", "Not authorized to view logs for this api_key_id")
    effective_key_id = caller.get("id")

    rows = _load("request_logs.json")

    def _row_dt(r):
        try:
            s = r.get("created_at")
            if isinstance(s, str):
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None
        return None

    # filter
    out = []
    for r in rows:
        if r.get("api_key_id") != effective_key_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        if keyword is not None:
            kw = r.get("keyword")
            if not isinstance(kw, str) or kw.strip() != keyword:
                continue
        if cache_hit is not None and r.get("cache_hit") != cache_hit:
            continue
        if fd is not None or td is not None:
            dt = _row_dt(r)
            if dt is None:
                continue
            if fd is not None and dt < fd:
                continue
            if td is not None and dt >= td:
                continue
        out.append(r)

    # sort
    reverse = (sort == "created_at_desc")
    def _sort_key(r):
        dt = _row_dt(r)
        # fall back to string
        return (dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), r.get("id") or "")
    out.sort(key=_sort_key, reverse=reverse)

    # apply cursor (exclusive)
    if cursor_created_at is not None and cursor_id is not None:
        filtered = []
        for r in out:
            dt = _row_dt(r) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            rid = r.get("id") or ""
            if reverse:
                # return entries strictly before (cursor_created_at, cursor_id) in desc ordering
                if (dt, rid) < (cursor_created_at, cursor_id):
                    filtered.append(r)
            else:
                if (dt, rid) > (cursor_created_at, cursor_id):
                    filtered.append(r)
        out = filtered

    page_rows = out[:limit]
    has_more = len(out) > len(page_rows)
    next_cursor = None
    if has_more and page_rows:
        last = page_rows[-1]
        next_cursor = f"{last.get('created_at')}|{last.get('id')}"

    # strip raw_response_ref to avoid payload exposure (also requested)
    def _sanitize(r):
        rr = dict(r)
        rr.pop("raw_response_ref", None)
        return rr

    caller_keys = _load("api_keys.json")
    # update last_used_at for caller
    now = _now_iso()
    for k in caller_keys:
        if k.get("id") == caller.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", caller_keys)

    _log_call(caller, "succeeded", duration_ms=int((time.time()-t0)*1000))

    return {
        "data": [_sanitize(r) for r in page_rows],
        "meta": {
            "total": len(out) + (0),  # total after cursor applied
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
        }
    }

def get_request_log(api_key, id, include_items=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0298000" if __import__("os").path.isdir("./environment_mix/0298000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _ulid_like(prefix):
        ms = int(time.time() * 1000)
        t = ms
        chars = []
        for _ in range(10):
            chars.append(_CROCKFORD[t % 32])
            t //= 32
        time_part = "".join(reversed(chars))
        r = int.from_bytes(os.urandom(10), "big")
        chars = []
        for _ in range(16):
            chars.append(_CROCKFORD[r % 32])
            r //= 32
        rand_part = "".join(reversed(chars))
        return f"{prefix}{time_part}{rand_part}"

    def _parse_iso(dtstr):
        if dtstr is None:
            return None
        if isinstance(dtstr, datetime.datetime):
            return dtstr
        if not isinstance(dtstr, str) or not dtstr:
            return None
        try:
            return datetime.datetime.fromisoformat(dtstr.replace("Z", "+00:00"))
        except Exception:
            return None

    def _day_start_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return datetime.datetime(dt.year, dt.month, dt.day, tzinfo=datetime.timezone.utc)

    def _canonical_json(obj):
        try:
            return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        except Exception:
            return None

    def _hash_cache_key(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _find_api_key_row(presented, api_keys_rows):
        # Authenticate by matching either id or client-visible prefix (never hash compare).
        if not isinstance(presented, str):
            return None
        p = presented.strip()
        if not p:
            return None
        # Prefer exact id match
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("id") == p:
                return r
        # Fallback: allow key_prefix match for "client-visible value"
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("key_prefix") == p:
                return r
        return None

    def _get_or_create_usage_counter(usage_rows, api_key_id, window_start_iso, now_iso):
        for r in usage_rows:
            if (
                isinstance(r, dict)
                and r.get("api_key_id") == api_key_id
                and r.get("window_type") == "day"
                and r.get("window_start") == window_start_iso
            ):
                return r
        newr = {
            "id": _ulid_like("nvs_usg_"),
            "api_key_id": api_key_id,
            "window_start": window_start_iso,
            "window_type": "day",
            "requests_total": 0,
            "requests_succeeded": 0,
            "requests_failed": 0,
            "result_items_total": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_rows.append(newr)
        return newr

    def _rate_limit_check(request_logs_rows, api_key_row, now_dt):
        # Token bucket computed from request_logs history (approximate but stateful via logs).
        rps = api_key_row.get("rate_limit_rps")
        burst = api_key_row.get("rate_limit_burst")
        try:
            rps = float(rps)
            burst = int(burst)
        except Exception:
            return False, _err("VALIDATION_ERROR", "API key rate limit configuration invalid.")
        if rps <= 0 or burst < 1:
            return False, _err("VALIDATION_ERROR", "API key rate limit configuration invalid.")

        cutoff = now_dt - datetime.timedelta(seconds=max(1, int(burst / rps) + 2))
        events = 0
        for r in request_logs_rows:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            created = _parse_iso(r.get("created_at"))
            if created is None:
                continue
            if created >= cutoff:
                events += 1
        # crude burst gate: allow at most burst requests inside cutoff window
        if events >= burst:
            return False, _err("RATE_LIMIT", "Rate limit exceeded for api_key.")
        return True, None

    # ---- Validate inputs ----
    if include_items is None:
        include_items = False
    if not isinstance(include_items, bool):
        return _err("VALIDATION_ERROR", "include_items must be a boolean.")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.")

    presented = api_key.strip()
    req_id = id.strip()

    start_ts = time.time()
    now = _now()
    now_iso = now.isoformat()

    # ---- Load datastore ----
    api_keys_rows = _load("api_keys.json")
    if isinstance(api_keys_rows, dict) and "rows" in api_keys_rows:
        api_keys_rows = api_keys_rows.get("rows")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []

    request_logs_rows = _load("request_logs.json")
    if isinstance(request_logs_rows, dict) and "rows" in request_logs_rows:
        request_logs_rows = request_logs_rows.get("rows")
    if not isinstance(request_logs_rows, list):
        request_logs_rows = []

    usage_rows = _load("usage_counters.json")
    if isinstance(usage_rows, dict) and "rows" in usage_rows:
        usage_rows = usage_rows.get("rows")
    if not isinstance(usage_rows, list):
        usage_rows = []

    items_rows = _load("search_result_items.json")
    if isinstance(items_rows, dict) and "rows" in items_rows:
        items_rows = items_rows.get("rows")
    if not isinstance(items_rows, list):
        items_rows = []

    # ---- Authenticate ----
    key_row = _find_api_key_row(presented, api_keys_rows)
    if not key_row:
        # Must still log invocation? Business rules say each tool invocation must create one request log row.
        # But request_logs requires api_key_id FK and active key; for invalid key we cannot create a valid row.
        # Therefore return UNAUTHORIZED without logging.
        return _err("UNAUTHORIZED", "Missing/invalid api_key.")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active.", api_key_id=key_row.get("id"), status=key_row.get("status"))

    # ---- Enforce rate limit before doing work, but after auth ----
    ok_rl, rl_err = _rate_limit_check(request_logs_rows, key_row, now)
    if not ok_rl:
        return rl_err

    # ---- Create request log row (received -> validated -> succeeded/failed) ----
    # This tool has no keyword/display/start/sort/filter semantics
    normalized_params = {"id": req_id, "include_items": bool(include_items)}
    norm_json = _canonical_json(normalized_params) or "{}"
    cache_scope = key_row.get("naver_client_id") or "default"
    cache_key = _hash_cache_key("get_request_log|" + norm_json + "|" + str(cache_scope))

    req_row = {
        "id": _ulid_like("nvs_req_"),
        "api_key_id": key_row.get("id"),
        "tool_name": "get_request_log",  # not in enum; keep vendor schema? In store enum lacks this tool.
        # However business rules provided tool_name enum excludes get_request_log; still must record invocations.
        # We will store tool_name as literal and not validate enum here to avoid rejecting valid call.
        "keyword": None,
        "page": None,
        "display": None,
        "start": None,
        "sort": None,
        "filter": None,
        "normalized_params": normalized_params,
        "cache_key": cache_key,
        "cache_hit": False,
        "status": "received",
        "upstream_endpoint": None,
        "upstream_http_status": None,
        "error_code": None,
        "error_message": None,
        "response_meta": None,
        "raw_response_ref": None,
        "result_items_count": 0,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # Note: request_logs.tool_name enum in schema doesn't include get_request_log, but datastore already has only search/correct tools.
    # To preserve "observable dynamics" without violating store too harshly, attempt to log with tool_name 'search_webkr' fallback
    # if strict consumers exist. But we should not fabricate other tool; still, schema says MUST log each invocation.
    # We'll keep actual name and persist; this local backend should tolerate it.
    request_logs_rows.append(req_row)

    # Update usage counters (requests_total increments on received)
    day_start = _day_start_utc(now)
    day_start_iso = day_start.isoformat()
    uc = _get_or_create_usage_counter(usage_rows, key_row.get("id"), day_start_iso, now_iso)

    # Quota check: requests_total MUST NOT exceed quota_day_requests
    quota_req = key_row.get("quota_day_requests")
    try:
        quota_req = int(quota_req)
    except Exception:
        quota_req = 0
    if quota_req < 0:
        quota_req = 0

    # Predict next total
    next_total = int(uc.get("requests_total") or 0) + 1
    if next_total > quota_req:
        # mark failed, persist logs + usage update
        req_row["status"] = "failed"
        req_row["error_code"] = "QUOTA_EXCEEDED_REQUESTS_DAY"
        req_row["error_message"] = "Daily request quota exceeded for api_key."
        req_row["updated_at"] = now_iso
        # usage: count received, and failed
        uc["requests_total"] = next_total
        uc["requests_failed"] = int(uc.get("requests_failed") or 0) + 1
        uc["updated_at"] = now_iso
        req_row["duration_ms"] = max(0, int((time.time() - start_ts) * 1000))
        _save("request_logs.json", request_logs_rows)
        _save("usage_counters.json", usage_rows)
        return _err("QUOTA_EXCEEDED", req_row["error_message"], error_code=req_row["error_code"])

    # Accept request into validated
    uc["requests_total"] = next_total
    uc["updated_at"] = now_iso
    req_row["status"] = "validated"
    req_row["updated_at"] = now_iso

    # ---- Fetch target request log ----
    target = None
    for r in request_logs_rows:
        if isinstance(r, dict) and r.get("id") == req_id:
            target = r
            break

    if not target:
        req_row["status"] = "failed"
        req_row["error_code"] = "NOT_FOUND"
        req_row["error_message"] = "request_logs row not found."
        req_row["updated_at"] = now_iso
        uc["requests_failed"] = int(uc.get("requests_failed") or 0) + 1
        uc["updated_at"] = now_iso
        req_row["duration_ms"] = max(0, int((time.time() - start_ts) * 1000))
        _save("request_logs.json", request_logs_rows)
        _save("usage_counters.json", usage_rows)
        return _err("NOT_FOUND", "request_logs row not found.", id=req_id)

    # Authorization to read: same api_key_id only
    if target.get("api_key_id") != key_row.get("id"):
        req_row["status"] = "failed"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "Not authorized to access this request log."
        req_row["updated_at"] = now_iso
        uc["requests_failed"] = int(uc.get("requests_failed") or 0) + 1
        uc["updated_at"] = now_iso
        req_row["duration_ms"] = max(0, int((time.time() - start_ts) * 1000))
        _save("request_logs.json", request_logs_rows)
        _save("usage_counters.json", usage_rows)
        return _err("UNAUTHORIZED", "Not authorized to access this request log.", id=req_id)

    # ---- Build response ----
    tool_name = target.get("tool_name")
    is_search_tool = isinstance(tool_name, str) and tool_name.startswith("search_")

    response = {"request_log": target}

    if include_items and is_search_tool:
        # Include items ordered by rank
        related = []
        for it in items_rows:
            if isinstance(it, dict) and it.get("request_id") == req_id:
                related.append(it)
        related.sort(key=lambda x: (x.get("rank") if isinstance(x.get("rank"), int) else 10**9, x.get("id") or ""))
        response["items"] = related
        response["items_count"] = len(related)
    else:
        response["items"] = None
        response["items_count"] = None

    # Mark succeeded
    req_row["status"] = "succeeded"
    req_row["updated_at"] = now_iso
    req_row["result_items_count"] = 0
    req_row["duration_ms"] = max(0, int((time.time() - start_ts) * 1000))

    # update usage succeeded/failed counts
    uc["requests_succeeded"] = int(uc.get("requests_succeeded") or 0) + 1
    uc["updated_at"] = now_iso

    # Update key last_used_at/updated_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso

    _save("request_logs.json", request_logs_rows)
    _save("usage_counters.json", usage_rows)
    _save("api_keys.json", api_keys_rows)

    return {
        "data": response,
        "meta": {
            "request_id": req_row["id"],
            "duration_ms": req_row["duration_ms"],
        },
    }
